import{_ as r,a0 as i,w as p,s as n,ao as d,I as a,x as e,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"谷歌會用基於信任的認證措施取代密碼嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"谷歌會用基於信任的認證措施取代密碼嗎？ | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"谷歌會用基於信任的認證措施取代密碼嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谷歌會用基於信任的認證措施取代密碼嗎？ | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method","title":"谷歌會用基於信任的認證措施取代密碼嗎？","tag":"201606","desc":""},"relativePath":"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method.md","filePath":"[post].md"}'),w={name:"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method.md"};function u(m,t,T,f,g,h){const o=i("Link");return p(),n("div",null,[t[13]||(t[13]=d('<h1 id="谷歌會用基於信任的認證措施取代密碼嗎" tabindex="-1">谷歌會用基於信任的認證措施取代密碼嗎？ <a class="header-anchor" href="#谷歌會用基於信任的認證措施取代密碼嗎" aria-label="Permalink to “谷歌會用基於信任的認證措施取代密碼嗎？”">​</a></h1><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/05/Trust-API-Google-replaces-passwords.jpg" alt=""></p><p>一個谷歌新開發的認證措施會評估你的登錄有多可靠，並且基於一個“信任分（Trust Score）”認證你的登錄。</p><p>這個谷歌項目的名字是 Abacus，它的目標是讓你擺脱討厭的密碼記憶和輸入。</p><p>在最近的 Google I/O 開發者大會上，谷歌引入了自這個雄心勃勃的項目而來的新特性，稱作“<strong>Trust API</strong>”。</p><p>“如果一切進展順利”，這個 API（Application Programming Interface，應用程序編程接口）會在年底前供安卓開發者使用。API 會利用安卓設備上不同的傳感器來識別用户，並創建一個他們稱之為“信任分（Trust Score）”的結果。</p><p>基於這個信任分，一個需要登錄認證的應用可以驗證你確實可以授權登錄，從而不會提示需要密碼。</p><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/05/Abacus-to-Trust-API.jpg" alt=""></p><p><em>Abacus 到 Trust API</em></p><h3 id="需要思考的地方" tabindex="-1">需要思考的地方 <a class="header-anchor" href="#需要思考的地方" aria-label="Permalink to “需要思考的地方”">​</a></h3><p>儘管這個想法，明智的功能，聽起來很棒——減輕了密碼認證的負擔。</p><p>但從另一面來説，這是不是谷歌又一次逼迫我們（有意或無意）為了方便使用而放棄我們的隱私？</p><p>是否值得？這取決於你的決定...</p><hr>',14)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),s(o,{href:"http://www.iwillfolo.com/will-google-replace-passwords-with-a-new-trust-based-authentication-method/"},{default:l(()=>[...t[0]||(t[0]=[e("http://www.iwillfolo.com/will-google-replace-passwords-with-a-new-trust-based-authentication-method/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),s(o,{href:"http://www.iwillfolo.com/"},{default:l(()=>[...t[2]||(t[2]=[e("iWillFolo",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),s(o,{href:"https://github.com/alim0x"},{default:l(()=>[...t[3]||(t[3]=[e("alim0x",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const C=r(w,[["render",u]]);export{x as __pageData,C as default};
